// Writes README.md from its sources (`pnpm turbo run build`); `--check` fails when README.md is stale.
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { type Content, type Plugin, REPO_URL, SITE_URL, loadContent, repoRoot } from "./content.ts";

function harnesses(p: Plugin): string {
  return [p.harness.claude && "Claude Code", p.harness.pi && "pi"].filter(Boolean).join(" / ");
}

export function render(c: Content): string {
  const out: string[] = [];
  out.push("# agents", "");
  out.push(
    "<!-- Generated by lib/tools/build/readme.ts (`turbo run build`) from apps/*/README.md, skills/*/SKILL.md and docs/. Edit those, not this file. -->",
    "",
  );
  out.push(c.intro, "");
  out.push(`Documentation, with a page per plugin and skill: **${SITE_URL}/**`, "");
  out.push("## Install", "", c.install, "");
  out.push("## Plugins", "");
  const ready = c.plugins.filter((p) => !p.status);
  for (const p of ready.filter((p) => p.featured)) {
    out.push(`### [${p.name}](${SITE_URL}/plugins/${p.name}/)`, "", p.tagline, "");
    // The poster of its first demo, from the site: the media are recorded there, not committed.
    out.push(
      `[![${p.name}](${SITE_URL}/media/${p.name}/demo.png)](${SITE_URL}/plugins/${p.name}/)`,
      "",
    );
  }
  const line = (p: Plugin) =>
    `- [${p.name}](${SITE_URL}/plugins/${p.name}/): ${p.tagline} (${harnesses(p)})`;
  const others = ready.filter((p) => !p.featured);
  if (others.length) out.push("More:", "", ...others.map(line), "");
  const unfinished = c.plugins.filter((p) => p.status === "in-progress");
  if (unfinished.length)
    out.push("In progress, and not ready for anyone else to use:", "", ...unfinished.map(line), "");
  out.push("## Skills", "");
  for (const cat of c.categories) {
    out.push(`### ${cat.title}`, "");
    if (cat.blurb) out.push(cat.blurb, "");
    for (const s of cat.skills)
      out.push(
        `- [${s.name}](${SITE_URL}/skills/${s.name}/): ${s.summary}${s.credit ? " " + s.credit : ""}${s.status ? " _(in progress)_" : ""}`,
      );
    out.push("");
  }
  out.push("## Development", "");
  out.push(
    `See [\`docs/\`](docs/) or the [developer pages](${SITE_URL}/dev/); the source is at ${REPO_URL}.`,
    "",
  );
  return out.join("\n").replace(/\n{3,}/g, "\n\n");
}

/** What is wrong with README.md: empty when it is the generator's output. */
export function checkReadme(root: string = repoRoot): string[] {
  const file = join(root, "README.md");
  const have = existsSync(file) ? readFileSync(file, "utf8") : "";
  return have === render(loadContent(root))
    ? []
    : ["README.md is stale: run `pnpm turbo run build` (then `pnpm turbo run fmt`) and commit it."];
}

// Imported by the invariants spec, which only calls `checkReadme`.
if (import.meta.main) {
  if (process.argv.includes("--check")) {
    const problems = checkReadme();
    if (problems.length) {
      console.error(problems.join("\n"));
      process.exit(1);
    }
  } else {
    writeFileSync(join(repoRoot, "README.md"), render(loadContent(repoRoot)));
  }
}
